SourceCode.Declaration:
class TFMRegistrationCollectorDecimal extends TFMRegistrationCollector
{
    int length;
    boolean performCalculation;
    real minimumValue;
    real maximumvalue;
    TFMPrimaryInputMethod   primaryInputMethod;

}

Method.Source:
public void new(int _id, str _name, str _header, str _label, str _helpLabel)
{
    super(_id, _name, _header, _label, _helpLabel);
    minimumValue = real2int(minint());
    maximumvalue = real2int(maxInt());;
    length = 14;
    primaryInputMethod = TFMPrimaryInputMethod::Scan;
}

[TFMCategory("@SYS103414", "The input method sets how the control is shown and works. ScanOnly - the text is not editable only by scan. Scan - The Scan Icon is displayed but can be edited. Control - No scan icon.")]
public TFMPrimaryInputMethod parmprimaryInputMethod(TFMPrimaryInputMethod   _primaryInputMethod = primaryInputMethod)
{
    primaryInputMethod = _primaryInputMethod;
    return primaryInputMethod;
}

public int parmLength(int _length = length)
{
    length = _length;
    return length;
}

[TFMCategory("@SYS103414", "If true then the input box will perform calculation e.g. if the input is 3 + 3 it will be caluculated to 6.")]
public boolean parmPerformCalculation(boolean _performCalculation = performCalculation)
{
    performCalculation = _performCalculation;
    return performCalculation;
}

public real parmminValue(real _minimumValue = minimumValue)
{
    minimumValue = _minimumValue;
    return minimumValue;
}

public real parmmaxValue(real _maximumvalue = maximumvalue)
{
    maximumvalue = _maximumvalue;
    return maximumvalue;
}

/// <summary>
/// Builds a registration collector for deciaml steps
/// </summary>
/// <param name="setEmpty"></param>
/// <param name="id"></param>
/// <param name="name"></param>
/// <param name="header"></param>
/// <param name="label"></param>
/// <param name="helpLabel"></param>
/// <param name="performCalculation">
/// controls whether the device will accept math expresions like 1.2+1.3 as input
/// </param>
/// <param name="defaultValue"></param>
/// <param name="minValue"></param>
/// <param name="maxValue"></param>
/// <param name="length"></param>
/// <param name="GS1valueId_Deci"></param>
/// identifiers for GS1-barcode prefixes
/// </param>
public static TFMRegistrationCollectorDecimal DecimalStep(
                                            int     _id,
                                            str     _name,
                                            str     _header,
                                            str     _label,
                                            str     _helpLabel,
                                            boolean _performCalculation = false,
                                            str     _defaultValue = '',
                                            real    _minValue = minInt(),
                                            real    _maxValue = maxInt(),
                                            int     _length = 14,
                                            str     _eanAI = '')
{
    TFMRegistrationCollectorDecimal collector = new TFMRegistrationCollectorDecimal(_id,_name,_header,_label,_helpLabel);
    collector.parmPerformCalculation(_performCalculation);
    collector.parmDefaultValue(_defaultValue);
    collector.parmMinValue(_minValue);
    collector.parmmaxValue(_maxValue);
    collector.parmLength(_length);
    collector.parmEanAI(_eanAI);
    return collector;
}

/// <summary>
/// Builds a registration collector for deciaml steps
/// </summary>
/// <param name="setEmpty"></param>
/// <param name="id"></param>
/// <param name="name"></param>
/// <param name="header"></param>
/// <param name="label"></param>
/// <param name="helpLabel"></param>
/// <param name="performCalculation">
/// controls whether the device will accept math expresions like 1.2+1.3 as input
/// </param>
/// <param name="defaultValue"></param>
/// <param name="minValue"></param>
/// <param name="maxValue"></param>
/// <param name="length"></param>
/// <param name="GS1valueId_Deci"></param>
/// identifiers for GS1-barcode prefixes
/// </param>
public static Map DecimalStepMap(
                                            int     _id,
                                            str     _name,
                                            str     _header,
                                            str     _label,
                                            str     _helpLabel,
                                            boolean _performCalculation = false,
                                            str     _defaultValue = '',
                                            real    _minValue = -100000000,
                                            real    _maxValue = 100000000,
                                            int     _length = 14,
                                            str     _eanAI = '')
{
    return TFMRegistrationCollectorDecimal::DecimalStep(_id,_name,_header,_label,_helpLabel,_performCalculation,_defaultValue,_minValue,_maxValue,_length,_eanAI).getMap();
}

